mapper.select:
select v.id, v.tree_id, v.category_node_id, coalesce(group_concat(distinct bn.node_name order by bn.node_id separator '、'), n.node_name) as category_node_name, v.vin, v.plate_no, v.brand, v.create_time from biz_vehicle v left join biz_tree_node n on n.node_id = v.category_node_id and n.del_flag = '0' left join biz_tree_category_bind cb on cb.business_type = 'vehicle' and cb.business_id = v.id and cb.del_flag = '0' left join biz_tree_node bn on bn.node_id = cb.node_id and bn.del_flag = '0'
v.del_flag = 0
and v.vin = #{bo.vin}
and v.plate_no = #{bo.plateNo}
and v.brand = #{bo.brand}
and v.tree_id = #{bo.treeId}
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'vehicle' and fcb.business_id = v.id and fcb.del_flag = '0' and fcb.node_id in
#{categoryNodeId}
)
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'vehicle' and fcb.business_id = v.id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
group by v.id, v.tree_id, v.category_node_id, n.node_name, v.vin, v.plate_no, v.brand, v.create_time order by v.id asc

